package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Native choice and gesture-only preview, fake sensor, private prefs, no real recording. */
public final class TrackingFlipFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);TrackingFlipFixture f;
 interface Task{void run()throws Exception;}interface Ready{boolean check()throws Exception;}
 void waitFor(Ready ready)throws Exception{long limit=SystemClock.elapsedRealtime()+10000;while(!ready.check()){if(SystemClock.elapsedRealtime()>limit)throw new AssertionError("flip fixture did not reach its expected state");Thread.sleep(30);}}
 View root(){for(View v:WindowInspector.getGlobalWindowViews())if(v.hasWindowFocus()&&v.isAttachedToWindow()&&v.getContext().getPackageName().equals(c.getPackageName()))return v;return null;}
 View find(View v,String label,boolean switches){if(v==null)return null;if((!switches||v instanceof Switch)&&(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&label.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){View found=find(g.getChildAt(n),label,switches);if(found!=null)return found;}}return null;}
 Rect control(String label,boolean switches){Rect[] result={null};i.runOnMainSync(()->{View v=find(root(),label,switches);while(v!=null&&!v.isClickable())v=v.getParent() instanceof View?(View)v.getParent():null;if(v==null||!v.isEnabled())return;Rect area=new Rect();if(v.getGlobalVisibleRect(area)&&area.height()==v.getHeight()&&area.width()==v.getWidth()&&v.getHeight()>=Design.dp(c,48)){int[] screen=new int[2];v.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+v.getWidth(),screen[1]+v.getHeight());}else v.requestRectangleOnScreen(new Rect(0,0,v.getWidth(),v.getHeight()),false);});return result[0];}
 void click(String label)throws Exception{click(label,false);}void click(String label,boolean switches)throws Exception{waitFor(()->control(label,switches)!=null);View[] owner={null};CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{owner[0]=root();assertNotNull(owner[0]);owner[0].getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner[0].invalidate();});assertTrue(commit.await(5,TimeUnit.SECONDS));Rect r=control(label,switches);assertNotNull(label,r);i.runOnMainSync(()->assertSame("Exact focused committed input owner",owner[0],root()));assertTrue(d.click(r.centerX(),r.centerY()));}
 void text(String label)throws Exception{waitFor(()->{boolean[] found={false};i.runOnMainSync(()->found[0]=find(root(),label,false)!=null);return found[0];});}
 File folder(){File f=new File(c.getExternalFilesDir(null),"verification");assertTrue(f.isDirectory()||f.mkdirs());return f;}
 void capture(String name,String label)throws Exception{text(label);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View v=root();assertNotNull(v);v.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);v.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));assertTrue(d.takeScreenshot(new File(folder(),"tracking-flip-"+name+".png")));}


 void ready()throws Exception{f.idle();waitFor(()->{boolean[] ok={false};i.runOnMainSync(()->ok[0]=root()!=null&&f.resumed instanceof TrackingFlipActivity&&((TrackingFlipActivity)f.resumed).drawn==f.job().state);return ok[0];});}
 void launch()throws Exception{f.launch();ready();}
 void recreate()throws Exception{Activity old=f.resumed;i.runOnMainSync(old::recreate);waitFor(()->f.resumed!=old&&f.resumed.hasWindowFocus());ready();}
 void run(Task action)throws Exception{try(TrackingFlipFixture fixture=new TrackingFlipFixture()){f=fixture;try{action.run();}catch(Exception|AssertionError error){try{d.takeScreenshot(new File(folder(),"tracking-flip-failure.png"));d.dumpWindowHierarchy(new File(folder(),"tracking-flip-failure.xml"));}catch(Exception capture){error.addSuppressed(capture);}throw error;}}}
 @Test public void defaultOffDraftSaveReopenAndFakeGesturePreview()throws Exception{run(()->{launch();capture("default","Use during movement tracking");assertFalse(TrackingFlipSettings.enabled(c));assertTrue(f.sensors.isEmpty());click("Use during movement tracking",true);waitFor(()->{boolean[] on={false};i.runOnMainSync(()->on[0]=((TrackingFlipActivity)f.resumed).draft);return on[0];});recreate();capture("draft-recreated","Save flip pause");assertFalse(TrackingFlipSettings.enabled(c));click("Save flip pause");waitFor(()->TrackingFlipSettings.enabled(c));ready();launch();capture("saved-reopened","Save flip pause");assertTrue(TrackingFlipSettings.enabled(c));assertTrue(f.sensors.isEmpty());click("Test gesture only");waitFor(()->!f.sensors.isEmpty()&&f.sensors.get(0).sink!=null);capture("preview","Stop gesture preview");i.runOnMainSync(()->{TrackingFlipFixture.Fake sensor=f.sensors.get(0);sensor.holdPose(-9.8,20);assertTrue(((TrackingFlipActivity)f.resumed).testing);sensor.holdPose(9.8,12);sensor.holdPose(-9.8,14);});capture("detected","Gesture detected. Recording was not changed.");assertNull(f.sensors.get(0).sink);assertEquals(0,f.sensors.get(0).holds);try(Store s=new Store(c,f.database)){assertTrue(s.rows("SELECT * FROM sessions").isEmpty());}});}
 @Test public void unsupportedAndLeavingPreviewKeepManualFallbackAndReleaseListener()throws Exception{run(()->{f.available=false;launch();click("Test gesture only");capture("unsupported","No accelerometer available. Use Pause manually.");assertFalse(TrackingFlipSettings.enabled(c));f.available=true;click("Test gesture only");waitFor(()->f.sensors.size()==2&&f.sensors.get(1).sink!=null);TrackingFlipSession.Sink stale=f.sensors.get(1).sink;recreate();capture("preview-stopped","Preview stopped when leaving this screen");assertNull(f.sensors.get(1).sink);i.runOnMainSync(()->{long now=SystemClock.elapsedRealtimeNanos();stale.sample(now,now,0,0,-9.8,true);assertFalse(((TrackingFlipActivity)f.resumed).testing);});assertFalse(TrackingFlipSettings.enabled(c));});}
}
